import { useState } from "react";

function CourseCard({ title, progress, onComplete }) {
  return (
    <article>
      <h3>{title}</h3>
      <progress max={100} value={progress}>{progress}%</progress>
      <button type="button" onClick={onComplete} disabled={progress === 100}>
        Mark complete
      </button>
    </article>
  );
}

export function Dashboard() {
  const [courses, setCourses] = useState([
    { id: "js", title: "JavaScript", progress: 40 },
    { id: "css", title: "CSS", progress: 90 },
  ]);

  function complete(id) {
    setCourses((list) => list.map((c) => (c.id === id ? { ...c, progress: 100 } : c)));
  }

  return courses.map((c) => (
    <CourseCard key={c.id} title={c.title} progress={c.progress} onComplete={() => complete(c.id)} />
  ));
}
